  (2, '2 - Central Trial Documents', '2.01', '2.01 - Product and Trial Documentation', '02.01.10', '02.01.10 - Report of Prior Investigations', 'To include reports of all prior clinical, animal and laboratory testing of the device and shall be comprehensive and adequate to justify the proposed investigation. Can be in addition or instead of an Investigator Brochure for device trials.', 'Report of Prior Investigations', 'Core', false, false, true, '01 First Country RA Approval', true, '03 Site Live / Ready / Open for Enrollment', false, 'Document Date', 2, 'Develop Study Design / Study Conduct'),
