  (2, '2 - Central Trial Documents', '2.01', '2.01 - Product and Trial Documentation', '02.01.11', '02.01.11 - Marketed Product Material', 'Materials available in the legal pharmacologic description of a drug or device, subject to detailed regulatory specifications, including approved chemical and proprietary names, description and classification, clinical pharmacology, approved indications and usage, contraindications, warnings, precautions, adverse reactions, drug abuse and dependence information, over dosage discussion, dosage and administration, formulations and appropriate references.', 'Package Insert', 'Core', true, false, true, '01 First Country RA Approval', true, '03 Site Live / Ready / Open for Enrollment', false, 'Version Date', 2, 'Develop Study Design / Study Conduct'),
  (2, '2 - Central Trial Documents', '2.01', '2.01 - Product and Trial Documentation', '02.01.11', '02.01.11 - Marketed Product Material', 'Materials available in the legal pharmacologic description of a drug or device, subject to detailed regulatory specifications, including approved chemical and proprietary names, description and classification, clinical pharmacology, approved indications and usage, contraindications, warnings, precautions, adverse reactions, drug abuse and dependence information, over dosage discussion, dosage and administration, formulations and appropriate references.', 'Summary of Product Characteristics', 'Core', true, false, true, '01 First Country RA Approval', true, '03 Site Live / Ready / Open for Enrollment', false, 'Version Date', 2, 'Develop Study Design / Study Conduct'),
