  (10, '10 - Data Management', '10.02', '10.02 - Data Capture', '10.02.01', '10.02.01 - CRF Completion Requirements', 'To provide detailed instructions on how data points on each CRF are to be completed; how to enter on paper and if EDC, how to enter data into the system.', 'CRF Completion Requirements', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Version Date', 3, 'Develop Study Design / Capture Subject Data'),
  (10, '10 - Data Management', '10.03', '10.03 - Database', '10.03.01', '10.03.01 - Database  Requirements', 'To provide a detailed design framework for the system(s) used to manage and store subject/patient data captured via a paper CRF or eCRF for the specified trial. Not to be confused with specifications for the Electronic Data Capture (EDC) system (see 10.04.02)', 'Database Requirements', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 3, 'Develop Study Design / Capture Subject Data'),
  (10, '10 - Data Management', '10.03', '10.03 - Database', '10.03.03', '10.03.03 - Edit Check Programming ', 'The computer code which satisfies the edit check plan/specification details; may include a reference to where the code resides.', 'Edit Check Programming', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 3, 'Develop Study Design / Capture Subject Data'),
  (10, '10 - Data Management', '10.03', '10.03 - Database', '10.03.07', '10.03.07 - Data Entry Guidelines (Paper)', 'To provide detailed instructions on how CRF data is to be entered into a database; specific to a paper CRF trial (therefore, would not be required with an EDC trial).', 'Data Entry Guidelines (Paper)', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 3, 'Develop Study Design / Capture Subject Data'),
