  (8, '8 - Central and Local Testing', '8.03', '8.03 - General', '08.03.03', '08.03.03 - Meeting Material', 'Agenda, presentation materials and other documentation generated during an internal or external zone-related meeting which documents any agreements or significant discussions. Includes meeting minutes or Q&A, attendance sheets and any pre-meeting material.', 'Agenda', 'Core', false, false, true, '11 Ongoing', true, '11 Ongoing', true, 'Meeting Start Date', 6, 'Secure Resources / Supplies'),
