  (1, '1 - Trial Management', '1.02', '1.02 - Trial Team', '01.02.01', '01.02.01 - Trial Team Details', 'To define trial roles, contact details and structure of the trial team - both sponsor and third parties; optionally this may include full and initials-only signature of all team members, role-to-role transition documents, organogram and/or team joining/leaving dates.', 'Trial Team Details', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', false, 'Document Date', 7, 'Secure Resources / People'),
  (1, '1 - Trial Management', '1.02', '1.02 - Trial Team', '01.02.01', '01.02.01 - Trial Team Details', 'To define trial roles, contact details and structure of the trial team - both sponsor and third parties; optionally this may include full and initials-only signature of all team members, role-to-role transition documents, organogram and/or team joining/leaving dates.', 'Transition Evidence', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', false, 'Document Date', 7, 'Secure Resources / People'),
  (1, '1 - Trial Management', '1.02', '1.02 - Trial Team', '01.02.02', '01.02.02 - Trial Team Curriculum Vitae', 'To document qualifications and eligibility of sponsor trial team members. Documentation for third party trial team members should be filed in Zone 09.', 'Trial Team Curriculum Vitae', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', false, 'Signature Date', 7, 'Secure Resources / People'),
  (2, '2 - Central Trial Documents', '2.01', '2.01 - Product and Trial Documentation', '02.01.05', '02.01.05 - Financial Disclosure Summary', 'Summary documentation of compliance with financial disclosure reporting requirements, per company and/or local government policies.  May include summaries, lists, other reports. ', 'Financial Disclosure Summary', 'Recommended', false, false, true, '10 Final Report / Clinical Study Report Approved', true, '10 Final Report / Clinical Study Report Approved', true, 'Version Date', 7, 'Secure Resources / People'),
  (5, '5 - Site Management', '5.01', '5.01 - Site Selection', '05.01.01', '05.01.01 - Site Contact Details', 'To document contact information for primary points of contact at the site (e.g. Principal Investigator, Institution Name, Trial Coordinator, Contracts Person, etc.).', 'Site Contact Details', 'Recommended', false, true, true, NULL, true, NULL, true, 'Document Date', 7, 'Secure Resources / People'),
  (5, '5 - Site Management', '5.01', '5.01 - Site Selection', '05.01.02', '05.01.02 - Confidentiality Agreement', 'A document between the sponsor and an outside party (Investigator or Institution) that defines the terms and basic criteria to assure that the party (or parties) receiving confidential information will maintain confidentiality and will not use that information for any purpose other than that described in the Agreement. May also be present in the Clinical Trial Agreement', 'Confidentiality Agreement', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 7, 'Secure Resources / People'),
  (5, '5 - Site Management', '5.01', '5.01 - Site Selection', '05.01.05', '05.01.05 - Sites Evaluated but not Selected', 'Documentation related to sites evaluated but not selected for the trial.', 'Sites Evaluated but not Selected', 'Recommended', true, false, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Document Date', 7, 'Secure Resources / People'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.03', '09.02.03 - Contractual Agreement', 'To document by a written dated signed agreement between two or more parties that defines any arrangements on delegation and distribution of tasks and obligations (including financial obligations); critical components include service description and budget.', 'Authorization To Proceed', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Signature Date', 7, 'Secure Resources / People'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.03', '09.02.03 - Contractual Agreement', 'To document by a written dated signed agreement between two or more parties that defines any arrangements on delegation and distribution of tasks and obligations (including financial obligations); critical components include service description and budget.', 'Budget', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Signature Date', 7, 'Secure Resources / People'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.03', '09.02.03 - Contractual Agreement', 'To document by a written dated signed agreement between two or more parties that defines any arrangements on delegation and distribution of tasks and obligations (including financial obligations); critical components include service description and budget.', 'Contract', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Signature Date', 7, 'Secure Resources / People'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.03', '09.02.03 - Contractual Agreement', 'To document by a written dated signed agreement between two or more parties that defines any arrangements on delegation and distribution of tasks and obligations (including financial obligations); critical components include service description and budget.', 'Change Order', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Signature Date', 7, 'Secure Resources / People'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.03', '09.02.03 - Contractual Agreement', 'To document by a written dated signed agreement between two or more parties that defines any arrangements on delegation and distribution of tasks and obligations (including financial obligations); critical components include service description and budget.', 'Data Privacy Agreements', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Signature Date', 7, 'Secure Resources / People'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.03', '09.02.03 - Contractual Agreement', 'To document by a written dated signed agreement between two or more parties that defines any arrangements on delegation and distribution of tasks and obligations (including financial obligations); critical components include service description and budget.', 'Indemnification', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Signature Date', 7, 'Secure Resources / People'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.17', '01.01.17 - Vendor Management Plan', 'To describe the overall management strategy for third party vendors used to conduct trial-related activities. May include assignment of responsibilities for third party vendor oversight, performance indicators, monitoring activities and schedules, issue escalation and resolution process, technology and documentation transfer and business continuity plan. Artifacts providing evidence of plan execution including, but not limited to: reports, checklists, etc. and other records demonstrating oversight of a specific third party vendor should be filed in the appropriate artifacts in Zone 09', 'Vendor Management Plan', 'Recommended', false, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 8, 'Secure Resources / Vendors'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.18', '01.01.18 - Roles and Responsibility Matrix', 'To identify range and distribution of tasks and responsibilities; may define internal assignment and all external parties; covers GCP as well as business process; often part of the Contractual Agreement (09.02.03).', 'Roles and Responsibility Matrix', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', false, 'Version Date', 8, 'Secure Resources / Vendors'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.19', '01.01.19 - Transfer of Regulatory Obligations ', 'To specify the transfer of regulatory obligations from sponsor to each Affiliate/CRO/Vendor and may include other agreements. A sponsor may transfer responsibility for any or all of the obligations set forth in this part to another entity. Any such transfer shall be described in writing. If not all obligations are transferred, the writing is required to describe each of the obligations being assumed by the alternate entity. If all obligations are transferred, a general statement that all obligations have been transferred is acceptable.', 'Transfer of Regulatory Obligations', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', false, 'Signature Date', 8, 'Secure Resources / Vendors'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.20', '01.01.20 - Operational Oversight', 'Documentation to show evidence of sponsor oversight of study, as well as any key decisions taken and the supporting rationale. Records demonstrating oversight of a specific third party should be filed in the appropriate artifacts in Zone 09.
', 'Operational Oversight Plan', 'Core', false, false, true, '04 First Monitoring Visit', false, NULL, false, 'Document Date', 8, 'Secure Resources / Vendors'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.20', '01.01.20 - Operational Oversight', 'Documentation to show evidence of sponsor oversight of study, as well as any key decisions taken and the supporting rationale. Records demonstrating oversight of a specific third party should be filed in the appropriate artifacts in Zone 09.
', 'Operational Oversight Evidence', 'Core', false, false, true, '04 First Monitoring Visit', false, NULL, false, 'Document Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.01', '08.01.01 - Certification or Accreditation', 'To document recognition and approval by an authorized accrediting body applying known acceptable standards, that the central or local facility is competent to perform required test(s) and support reliability of results; if applicable.', 'Certification or Accreditation', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Effective Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.01', '08.01.01 - Certification or Accreditation', 'To document recognition and approval by an authorized accrediting body applying known acceptable standards, that the central or local facility is competent to perform required test(s) and support reliability of results; if applicable.', 'CAP Certificate', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Effective Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.01', '08.01.01 - Certification or Accreditation', 'To document recognition and approval by an authorized accrediting body applying known acceptable standards, that the central or local facility is competent to perform required test(s) and support reliability of results; if applicable.', 'CLIA Certificate', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Effective Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.01', '08.01.01 - Certification or Accreditation', 'To document recognition and approval by an authorized accrediting body applying known acceptable standards, that the central or local facility is competent to perform required test(s) and support reliability of results; if applicable.', 'ISO Certification', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Effective Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.01', '08.01.01 - Certification or Accreditation', 'To document recognition and approval by an authorized accrediting body applying known acceptable standards, that the central or local facility is competent to perform required test(s) and support reliability of results; if applicable.', 'Other Certification or Accreditation', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Effective Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.02', '08.01.02 - Laboratory Validation Documentation ', 'To document through use of control data that a central or local laboratory can consistently and reproducibly report results that are reliable; may include but is not limited to reporting of calibration and control results for a research test parameter, antibody or pharmacokinetic testing that may be performed by an internal or external central or local laboratory; required if certification or accreditation is not available for the study test method.', 'Laboratory Validation Documentation', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Document Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.02', '08.01.02 - Laboratory Validation Documentation ', 'To document through use of control data that a central or local laboratory can consistently and reproducibly report results that are reliable; may include but is not limited to reporting of calibration and control results for a research test parameter, antibody or pharmacokinetic testing that may be performed by an internal or external central or local laboratory; required if certification or accreditation is not available for the study test method.', 'Laboratory System Specifications', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Document Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.02', '08.01.02 - Laboratory Validation Documentation ', 'To document through use of control data that a central or local laboratory can consistently and reproducibly report results that are reliable; may include but is not limited to reporting of calibration and control results for a research test parameter, antibody or pharmacokinetic testing that may be performed by an internal or external central or local laboratory; required if certification or accreditation is not available for the study test method.', 'Laboratory Kit Assembly Specifications', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', true, 'Document Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.08', '08.01.08 - Standardization Methods  ', 'To confirm that two or more central or local facilities can perform the same test / procedure and obtain consistent results; includes but may not be limited to cross-calibration of test methods between assays or facilities or phantom data or bioanalytical assay.', 'Analytical Method Report', 'Core', true, false, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', true, 'Document Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.08', '08.01.08 - Standardization Methods  ', 'To confirm that two or more central or local facilities can perform the same test / procedure and obtain consistent results; includes but may not be limited to cross-calibration of test methods between assays or facilities or phantom data or bioanalytical assay.', 'Interlaboratory Comparison Testing', 'Core', true, false, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', true, 'Document Date', 8, 'Secure Resources / Vendors'),
  (8, '8 - Central and Local Testing', '8.01', '8.01 - Facility Documentation', '08.01.08', '08.01.08 - Standardization Methods  ', 'To confirm that two or more central or local facilities can perform the same test / procedure and obtain consistent results; includes but may not be limited to cross-calibration of test methods between assays or facilities or phantom data or bioanalytical assay.', 'Standardization Methods', 'Core', true, false, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', true, 'Document Date', 8, 'Secure Resources / Vendors'),
  (9, '9 - Third parties ', '9.01', '9.01 - Third Party Oversight', '09.01.01', '09.01.01 - Qualification and Compliance', 'To confirm that a third party meets all relevant criteria to fulfill a contractual obligation; may include a quality questionnaire, a visit report to qualify their capabilities, other documents that support capabilities.', 'Evidence of Third Party Qualification', 'Core', false, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Document Date', 8, 'Secure Resources / Vendors'),
  (9, '9 - Third parties ', '9.01', '9.01 - Third Party Oversight', '09.01.01', '09.01.01 - Qualification and Compliance', 'To confirm that a third party meets all relevant criteria to fulfill a contractual obligation; may include a quality questionnaire, a visit report to qualify their capabilities, other documents that support capabilities.', 'Third Party Audit Certificate', 'Core', false, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Document Date', 8, 'Secure Resources / Vendors'),
  (9, '9 - Third parties ', '9.01', '9.01 - Third Party Oversight', '09.01.02', '09.01.02 - Third Party Curriculum Vitae', 'To document qualifications and eligibility of Individual Third Party Trial Team Members; CVs, Questionnaires etc. including translators, for the project. Not intended to duplicate records filed in Zones 1 and 5 (sponsor & investigator).', 'Third Party Curriculum Vitae', 'Core', false, true, true, '11 Ongoing', true, '11 Ongoing', false, 'Signature Date', 8, 'Secure Resources / Vendors'),
  (9, '9 - Third parties ', '9.01', '9.01 - Third Party Oversight', '09.01.03', '09.01.03 - Ongoing Third Party Oversight', 'To confirm throughout the duration of a study that a third party continues to meet all relevant criteria to fulfill a contractual obligation.', 'Ongoing Third Party Oversight', 'Recommended', true, true, true, '11 Ongoing', true, '11 Ongoing', false, 'Document Date', 8, 'Secure Resources / Vendors'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.01', '09.02.01 - Confidentiality Agreement', 'To confirm by written legal agreement that key information between parties will be prevented from being inappropriately disclosed. May be included in another contractual agreement.', 'Third Party Confidentiality Agreement', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Signature Date', 8, 'Secure Resources / Vendors'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.02', '09.02.02 - Vendor Selection', 'To identify how a third party was selected. May include details of other third parties short-listed, master vendor list and any assessments carried out prior to selection.', 'Vendor Evaluation', 'Recommended', false, false, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Document Date', 8, 'Secure Resources / Vendors'),
  (9, '9 - Third parties ', '9.02', '9.02 - Third Party Set-up', '09.02.02', '09.02.02 - Vendor Selection', 'To identify how a third party was selected. May include details of other third parties short-listed, master vendor list and any assessments carried out prior to selection.', 'Vendor Decision', 'Recommended', false, false, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Document Date', 8, 'Secure Resources / Vendors'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.01', '01.03.01 - Committee Process', 'To describe the purpose and mode of operation/manner of working of the Independent Trial Committee, which may be established by the sponsor to assess at intervals the progress of a clinical trial the safety data and the critical efficacy endpoints and to recommend to the sponsor whether to continue, modify or stop a trial. To describe in advance the decision-making process of the Committee that will evaluate key trial events (e.g. endpoints). Committee Types may include but not limited to: DMC, DSMB, National, Steering, Scientific, Internal DMC, Device, Dose Escalation, Safety Evaluation, Adjudication, Clinical Events Coordination. These may be used as sub-artifacts or metadata. Applies to all Committee artifacts', 'Committee Charter', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.01', '01.03.01 - Committee Process', 'To describe the purpose and mode of operation/manner of working of the Independent Trial Committee, which may be established by the sponsor to assess at intervals the progress of a clinical trial the safety data and the critical efficacy endpoints and to recommend to the sponsor whether to continue, modify or stop a trial. To describe in advance the decision-making process of the Committee that will evaluate key trial events (e.g. endpoints). Committee Types may include but not limited to: DMC, DSMB, National, Steering, Scientific, Internal DMC, Device, Dose Escalation, Safety Evaluation, Adjudication, Clinical Events Coordination. These may be used as sub-artifacts or metadata. Applies to all Committee artifacts', 'Committee Process', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.02', '01.03.02 - Committee Member List', 'To describe the purpose and mode of operation/manner of working of the Independent Trial Committee, which may be established by the sponsor to assess at intervals the progress of a clinical trial the safety data and the critical efficacy endpoints and to recommend to the sponsor whether to continue, modify or stop a trial. To describe in advance the decision-making process of the Committee that will evaluate key trial events (e.g. endpoints). Committee Types may include but not limited to: DMC, DSMB, National, Steering, Scientific, Internal DMC, Device, Dose Escalation, Safety Evaluation, Adjudication, Clinical Events Coordination. These may be used as sub-artifacts or metadata. Applies to all Committee artifacts', 'Committee Member List', 'Core', true, false, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.04', '01.03.04 - Committee Member Curriculum Vitae', 'To document qualifications and eligibility of the Committee Member to provide assessments, at set intervals, the progress of a clinical trial, of the safety data and the critical efficacy endpoints and to recommend to the sponsor whether to continue, modify or stop a trial. To include updates.', 'Committee Member Curriculum Vitae', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Signature Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.04', '01.03.04 - Committee Member Curriculum Vitae', 'To document qualifications and eligibility of the Committee Member to provide assessments, at set intervals, the progress of a clinical trial, of the safety data and the critical efficacy endpoints and to recommend to the sponsor whether to continue, modify or stop a trial. To include updates.', 'Committee Member Medical License', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Signature Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.04', '01.03.04 - Committee Member Curriculum Vitae', 'To document qualifications and eligibility of the Committee Member to provide assessments, at set intervals, the progress of a clinical trial, of the safety data and the critical efficacy endpoints and to recommend to the sponsor whether to continue, modify or stop a trial. To include updates.', 'Committee Member Training Evidence', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Signature Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.05', '01.03.05 - Committee Member Financial Disclosure Form', 'To certify that no financial arrangements with a Committee Member have been made where study outcome could affect compensation; that the Committee Member has no proprietary interest in the tested product; that the Committee Member does not have a significant equity interest in the sponsor of the covered study, that the Committee Member has not received significant payments of other sorts; and/or disclosure of specified financial arrangements and any steps taken to minimize the potential for bias.', 'Committee Member Financial Disclosure Form', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Signature Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.06', '01.03.06 - Committee Member Contract', 'To document agreement of trial requirements between sponsor or 3rd Party and Committee Member.', 'Committee Member', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Signature Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.03', '1.03 - Trial Committee', '01.03.07', '01.03.07 - Committee Member Confidentiality Disclosure Agreement', 'A document between the sponsor and the Committee Member that defines the terms and basic criteria to assure that the party (or parties) receiving confidential information will maintain confidentiality and will not use that information for any purpose other than that described in the Agreement.', 'Committee Member Confidentiality Disclosure Agreement', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Signature Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.04', '1.04 - Meetings', '01.04.04', '01.04.04 - Trial Team Evidence of Training', 'To document completion of study-specific trial team training, including certification or evidence of training (attendance sheets). Includes EDC training. Does not include each individual''s education, training and experience to perform his/her role. This should be doucmentated documented in the company learning management system.', 'Trial Team Training Attendance Sheet', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', false, 'Training Date', 10, 'Secure Resources / Committees'),
  (1, '1 - Trial Management', '1.04', '1.04 - Meetings', '01.04.04', '01.04.04 - Trial Team Evidence of Training', 'To document completion of study-specific trial team training, including certification or evidence of training (attendance sheets). Includes EDC training. Does not include each individual''s education, training and experience to perform his/her role. This should be doucmentated documented in the company learning management system.', 'Trial Team Training Certificate', 'Core', true, true, true, '02 Clinical Infrastructure Ready', true, '03 Site Live / Ready / Open for Enrollment', false, 'Training Date', 10, 'Secure Resources / Committees'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.20', '05.02.20 - Coordinating Investigator Documentation', 'Documentation to show the approval of a coordinating investigator for a specific region or group of investigators that is not already captured as another artifact for that investigator. Documentation related to a Country''s National Coordinator when they are not participating as an Investigator in the trial.', 'Coordinating Investigator Clinical Trial Agreement', 'Recommended', false, false, false, NULL, true, '03 Site Live / Ready / Open for Enrollment', false, 'Document Date', 10, 'Secure Resources / Committees'),
