  (3, '3 - Regulatory', '3.01', '3.01 - Trial Approval', '03.01.04', '03.01.04 - Public Registration ', 'Documentation related to registration of clinical trials in public registries such as ClinicalTrials.gov and to submission of results periodically during the study and at study completion.', 'Public Registration', 'Core', false, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Registration Date', 11, 'Notify Regulatory Agency of Trial'),
  (3, '3 - Regulatory', '3.01', '3.01 - Trial Approval', '03.01.04', '03.01.04 - Public Registration ', 'Documentation related to registration of clinical trials in public registries such as ClinicalTrials.gov and to submission of results periodically during the study and at study completion.', 'Receipt of Acknowledgement', 'Core', false, true, true, '02 Clinical Infrastructure Ready', true, '02 Clinical Infrastructure Ready', false, 'Registration Date', 11, 'Notify Regulatory Agency of Trial'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.01', '01.01.01 - Trial Master File Plan', 'To describe how records for the trial will be managed and stored during and after the trial, including study-specific processes and documentation for archiving and destruction. To include TMF filing structure to be used. May include TMF content list, filing structure and chain of custody records. Artifact can include any evidence of plan execution including, but not limited to: plan, reports, checklists, etc.', 'Document Transfer Documentation', 'Recommended', true, false, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 12, 'Develop Trial Management Strategy'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.01', '01.01.01 - Trial Master File Plan', 'To describe how records for the trial will be managed and stored during and after the trial, including study-specific processes and documentation for archiving and destruction. To include TMF filing structure to be used. May include TMF content list, filing structure and chain of custody records. Artifact can include any evidence of plan execution including, but not limited to: plan, reports, checklists, etc.', 'Evidence of Quality Review', 'Recommended', true, false, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 12, 'Develop Trial Management Strategy'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.01', '01.01.01 - Trial Master File Plan', 'To describe how records for the trial will be managed and stored during and after the trial, including study-specific processes and documentation for archiving and destruction. To include TMF filing structure to be used. May include TMF content list, filing structure and chain of custody records. Artifact can include any evidence of plan execution including, but not limited to: plan, reports, checklists, etc.', 'Request to Lock TMF', 'Recommended', true, false, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 12, 'Develop Trial Management Strategy'),
