  (10, '10 - Data Management', '10.03', '10.03 - Database', '10.03.02', '10.03.02 - Edit Check Plan', 'Specifications which will detect data that is illogical, unexpected, missing, redundant, or is outside of defined study parameters; usually implemented via programming logic', 'Edit Check Plan', 'Core', true, true, true, '02 Clinical Infrastructure Ready', false, NULL, false, 'Version Date', 12, 'Develop Trial Management Strategy'),
