  (3, '3 - Regulatory', '3.01', '3.01 - Trial Approval', '03.01.03', '03.01.03 - Notification of Regulatory Identification Number', 'Document identifying unique Identification (ID) number used to uniquely identify the trial or the trial level in that region, assigned by a regulatory agency – e.g. EU = EudraCT Number, FDA = IND Number, US Device = IDE Number.', 'Notification of Regulatory Identification Number', 'Core', false, false, false, NULL, true, '03 Site Live / Ready / Open for Enrollment', false, 'Notification Date', 14, 'Secure Regulatory Approval'),
