  (4, '4 - IRB or IEC and other Approvals', '4.01', '4.01 - IRB or IEC Trial Approval', '04.01.05', '04.01.05 - IRB or IEC Compliance Documentation', 'Documentation that the IRB/IEC is performing its function according to written operating procedures and is in compliance with GCP and applicable regulatory requirements.', 'Other Approval Committee Submissions', 'Core', true, false, false, NULL, true, '03 Site Live / Ready / Open for Enrollment', true, 'Document Date', 15, 'Secure Other Approvals'),
  (4, '4 - IRB or IEC and other Approvals', '4.02', '4.02 - Other Committees', '04.02.01', '04.02.01 - Other Submissions', 'A set of documents describing the trial or changes/updates to the trial submitted to a committee other than the IRB/IEC for approval. To include: Submissions and Correspondence 

The submitted study documents such as Investigator Brochure, Informed Consent Forms, etc. may or may not be filed as a complete dossier within this artifact.', 'Other Approval Committee Decisions', 'Recommended', false, false, false, NULL, true, '03 Site Live / Ready / Open for Enrollment', true, 'Submission Date', 15, 'Secure Other Approvals'),
  (4, '4 - IRB or IEC and other Approvals', '4.02', '4.02 - Other Committees', '04.02.02', '04.02.02 - Other Approvals', 'Approval documentation received from a committee other than the IRB/IEC in response to submission indicating approval/acknowledgement of trial specifications or modifications. To include: Submissions and Correspondence

Records referenced by the approval (such as a Protocol that has been approved) should be filed elsewhere in the TMF, as appropriate, as long as there is identification of the approved record within the committee letter or acknowledgement.', 'Other Approval Committee Decisions', 'Core', false, true, false, NULL, true, '03 Site Live / Ready / Open for Enrollment', true, 'Approval Date', 15, 'Secure Other Approvals'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.11', '01.01.11 - Debarment Statement', 'To verify whether the applicant or any of its principals is currently debarred, suspended, proposed for debarment, or declared ineligible to receive federal awards; whether within the past three years the applicant, or any of its principals, has been convicted of or had a civil judgment rendered against it for, or been indicted for, commission of fraud or certain criminal offenses; and whether the applicant has had any federal award terminated for cause or default in the past three years. Often part of the site qualification process, however, can account for situations which might arise during the course of the study, especially relevant for long-term trials.', 'Debarment Statement', 'Recommended', false, false, true, '#2 Clinical Infrastructure Ready', false, NULL, true, 'Document Date', 16, 'Set up site(s)'),
  (1, '1 - Trial Management', '1.01', '1.01 - Trial Oversight', '01.01.11', '01.01.11 - Debarment Statement', 'To verify whether the applicant or any of its principals is currently debarred, suspended, proposed for debarment, or declared ineligible to receive federal awards; whether within the past three years the applicant, or any of its principals, has been convicted of or had a civil judgment rendered against it for, or been indicted for, commission of fraud or certain criminal offenses; and whether the applicant has had any federal award terminated for cause or default in the past three years. Often part of the site qualification process, however, can account for situations which might arise during the course of the study, especially relevant for long-term trials.', 'Restricted Party Lists', 'Recommended', false, false, true, '#2 Clinical Infrastructure Ready', false, NULL, true, 'Document Date', 16, 'Set up site(s)'),
  (2, '2 - Central Trial Documents', '2.01', '2.01 - Product and Trial Documentation', '02.01.06', '02.01.06 - Insurance', 'To document that compensation to subject(s) for trial-related injury will be available. May include policy and certificates, terms and conditions. Certificate is core, policy is recommended.', 'Insurance Policy', 'Core', true, true, true, '01 First Country RA Approval', true, '03 Site Live / Ready / Open for Enrollment', false, 'Effective Date', 16, 'Set up site(s)'),
  (2, '2 - Central Trial Documents', '2.01', '2.01 - Product and Trial Documentation', '02.01.06', '02.01.06 - Insurance', 'To document that compensation to subject(s) for trial-related injury will be available. May include policy and certificates, terms and conditions. Certificate is core, policy is recommended.', 'Insurance Certificate', 'Core', true, true, true, '01 First Country RA Approval', true, '03 Site Live / Ready / Open for Enrollment', false, 'Effective Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.01', '5.01 - Site Selection', '05.01.04', '05.01.04 - Pre Trial Monitoring Report', 'To document onsite visit to determine qualification of site to participate in the trial. For example may include the following documentation: EDC qualification, Confirmation Letters / Emails, site profile form.', 'Pre Trial Monitoring Report', 'Core', true, true, false, NULL, false, NULL, true, 'Visit Start Date', 16, 'Set up site(s)'),
