  (5, '5 - Site Management', '5.01', '5.01 - Site Selection', '05.01.04', '05.01.04 - Pre Trial Monitoring Report', 'To document onsite visit to determine qualification of site to participate in the trial. For example may include the following documentation: EDC qualification, Confirmation Letters / Emails, site profile form.', 'Pre Trial Visit Follow Up Letter', 'Core', true, true, false, NULL, false, NULL, true, 'Visit Start Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.01', '5.01 - Site Selection', '05.01.04', '05.01.04 - Pre Trial Monitoring Report', 'To document onsite visit to determine qualification of site to participate in the trial. For example may include the following documentation: EDC qualification, Confirmation Letters / Emails, site profile form.', 'Pre Trial Visit Waiver', 'Core', true, true, false, NULL, false, NULL, true, 'Visit Start Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.01', '5.01 - Site Selection', '05.01.04', '05.01.04 - Pre Trial Monitoring Report', 'To document onsite visit to determine qualification of site to participate in the trial. For example may include the following documentation: EDC qualification, Confirmation Letters / Emails, site profile form.', 'Site Selection Letter', 'Core', true, true, false, NULL, false, NULL, true, 'Visit Start Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.01', '05.02.01 - Acceptance of Investigator Brochure', 'To document that relevant and current scientific information about the investigational product has been provided to the investigator.', 'Acceptance of Investigator Brochure', 'Recommended', true, false, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.01', '05.02.01 - Acceptance of Investigator Brochure', 'To document that relevant and current scientific information about the investigational product has been provided to the investigator.', 'Evidence of Investigator Brochure Distribution', 'Recommended', true, false, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
