  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.02', '05.02.02 - Protocol Signature Page', 'To document investigator and sponsor agreement to the protocol.', 'Protocol Signature Page', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.03', '05.02.03 - Protocol Amendment Signature Page', 'To document investigator and sponsor agreement to the protocol amendment.', 'Protocol Amendment Signature Page', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.04', '05.02.04 - Principal Investigator Curriculum Vitae', 'To document qualifications and eligibility of the Principal Investigator to conduct trial and/or provide medical supervision of subjects. To include updates, one-page CVs and biographical sketches.', 'Principal Investigator Affiliation Form', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.04', '05.02.04 - Principal Investigator Curriculum Vitae', 'To document qualifications and eligibility of the Principal Investigator to conduct trial and/or provide medical supervision of subjects. To include updates, one-page CVs and biographical sketches.', 'Principal Investigator Biographical Sketch', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.04', '05.02.04 - Principal Investigator Curriculum Vitae', 'To document qualifications and eligibility of the Principal Investigator to conduct trial and/or provide medical supervision of subjects. To include updates, one-page CVs and biographical sketches.', 'Principal Investigator Curriculum Vitae', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.05', '05.02.05 - Sub-Investigator Curriculum Vitae', 'To document qualifications and eligibility of any sub-Investigators to conduct trial and/or provide medical supervision of subjects. Sub-Investigators include any individual member of the clinical trial team designated and supervised by the investigator at a trial site to perform critical study trial-related procedures and/or to make important trial-related decisions (e.g., associates, residents, research fellows). To include updates, one-page CVs and biographical sketches', 'Sub-Investigator Affiliation Form', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.05', '05.02.05 - Sub-Investigator Curriculum Vitae', 'To document qualifications and eligibility of any sub-Investigators to conduct trial and/or provide medical supervision of subjects. Sub-Investigators include any individual member of the clinical trial team designated and supervised by the investigator at a trial site to perform critical study trial-related procedures and/or to make important trial-related decisions (e.g., associates, residents, research fellows). To include updates, one-page CVs and biographical sketches', 'Sub-Investigator Biographical Sketch', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.05', '05.02.05 - Sub-Investigator Curriculum Vitae', 'To document qualifications and eligibility of any sub-Investigators to conduct trial and/or provide medical supervision of subjects. Sub-Investigators include any individual member of the clinical trial team designated and supervised by the investigator at a trial site to perform critical study trial-related procedures and/or to make important trial-related decisions (e.g., associates, residents, research fellows). To include updates, one-page CVs and biographical sketches', 'Sub-Investigator Curriculum Vitae', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.06', '05.02.06 - Other Curriculum Vitae', 'To document qualifications and eligibility of site personnel other than the Principal Investigator or Sub-Investigators to conduct trial and/or provide medical supervision of subjects.', 'Other Affiliation Form', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.06', '05.02.06 - Other Curriculum Vitae', 'To document qualifications and eligibility of site personnel other than the Principal Investigator or Sub-Investigators to conduct trial and/or provide medical supervision of subjects.', 'Other Biographical Sketch', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.06', '05.02.06 - Other Curriculum Vitae', 'To document qualifications and eligibility of site personnel other than the Principal Investigator or Sub-Investigators to conduct trial and/or provide medical supervision of subjects.', 'Other Curriculum Vitae', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.07', '05.02.07 - Site Staff Qualification Supporting Information', 'To document site staff qualifications not previously outlined on CVs. May include list of studies, publications, training certificates for specific examinations, ICH-GCP training, site GCP or trial licensure, medical licenses, Human Subjects Protection Training, etc.', 'DEA License', 'Recommended', false, true, false, NULL, false, NULL, true, 'Effective Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.07', '05.02.07 - Site Staff Qualification Supporting Information', 'To document site staff qualifications not previously outlined on CVs. May include list of studies, publications, training certificates for specific examinations, ICH-GCP training, site GCP or trial licensure, medical licenses, Human Subjects Protection Training, etc.', 'Evidence of Registration', 'Recommended', false, true, false, NULL, false, NULL, true, 'Effective Date', 16, 'Set up site(s)'),
