  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.08', '05.02.08 - Form FDA 1572', 'For IND trial, 1572 must be completed globally for FDA submission.', 'Form FDA 1572', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.09', '05.02.09 - Investigator Regulatory Agreement', 'A regulatory statement from the investigator required by certain health authorities e.g. includes but is not limited to ‘Qualified Investigator Undertaking’ form and ‘Clinical Trial Site Information’ form required by Health Canada.', 'Clinical Trial Site Information Form', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.09', '05.02.09 - Investigator Regulatory Agreement', 'A regulatory statement from the investigator required by certain health authorities e.g. includes but is not limited to ‘Qualified Investigator Undertaking’ form and ‘Clinical Trial Site Information’ form required by Health Canada.', 'Investigator Regulatory Agreement', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.09', '05.02.09 - Investigator Regulatory Agreement', 'A regulatory statement from the investigator required by certain health authorities e.g. includes but is not limited to ‘Qualified Investigator Undertaking’ form and ‘Clinical Trial Site Information’ form required by Health Canada.', 'Qualified Investigator Undertaking Form', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.10', '05.02.10 - Financial Disclosure Form', 'To document financial disclosures, certification documentation and conflicts of interest, which include but are not limited to: completed disclosure forms of financial interests and arrangements of clinical investigators', 'Financial Disclosure Form', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.11', '05.02.11 - Data Privacy Agreement', 'To document agreement between sponsor and Site Staff (e.g., national or regional data privacy requirements); often contained in Clinical Trial Agreement', 'Data Privacy Agreement', 'Recommended', false, false, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.12', '05.02.12 - Clinical Trial Agreement', 'To document agreement of trial requirements between sponsor or 3rd Party and site/ PI. Includes indemnity unless separate document created.', 'Clinical Trial Agreement', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.12', '05.02.12 - Clinical Trial Agreement', 'To document agreement of trial requirements between sponsor or 3rd Party and site/ PI. Includes indemnity unless separate document created.', 'Clinical Trial Agreement with Investigator', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.12', '05.02.12 - Clinical Trial Agreement', 'To document agreement of trial requirements between sponsor or 3rd Party and site/ PI. Includes indemnity unless separate document created.', 'Clinical Trial Agreement with Investigator and Site', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.12', '05.02.12 - Clinical Trial Agreement', 'To document agreement of trial requirements between sponsor or 3rd Party and site/ PI. Includes indemnity unless separate document created.', 'Clinical Trial Agreement with Site', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.12', '05.02.12 - Clinical Trial Agreement', 'To document agreement of trial requirements between sponsor or 3rd Party and site/ PI. Includes indemnity unless separate document created.', 'Termination Agreement', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.13', '05.02.13 - Indemnity', 'To provide legal protection "as required by country regulations" in the event of an unforeseen adverse circumstance arising during the course of a clinical trial. May be in Clinical Trial Agreement', 'Indemnity', 'Core', true, true, false, NULL, true, NULL, true, 'Effective Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.17', '05.02.17 - IP Site Release Documentation', 'To document approval for sites to receive drug supply / investigational product.', 'IP Site Release Checklist', 'Recommended', true, false, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.17', '05.02.17 - IP Site Release Documentation', 'To document approval for sites to receive drug supply / investigational product.', 'IP Site Release Documentation', 'Recommended', true, false, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.17', '05.02.17 - IP Site Release Documentation', 'To document approval for sites to receive drug supply / investigational product.', 'IP Site Release Notification', 'Recommended', true, false, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.18', '05.02.18 - Site Signature Sheet', 'To document delegation by the Principal Investigator of trial specific tasks to site personnel conducting the trial.', 'Delegation of Authority Log', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
  (5, '5 - Site Management', '5.02', '5.02 - Site Set-up ', '05.02.18', '05.02.18 - Site Signature Sheet', 'To document delegation by the Principal Investigator of trial specific tasks to site personnel conducting the trial.', 'Site Signature Sheet', 'Core', true, true, false, NULL, false, NULL, true, 'Signature Date', 16, 'Set up site(s)'),
